$planner=Read 'Construction/AICF_ConstructionPlanner.c'
$metadata=Read 'Construction/AICF_ConstructionMetadata.c'
$profile=Read 'Content/AICF_ContentProfile.c'
$rhs=[IO.File]::ReadAllText((Join-Path $RepositoryRoot 'AIConflictArlandRHS/Scripts/Game/AIConflictArlandRHS/Content/AICF_RHSContentProfile.c'))
$quote=(Body (Read 'Command/AICF_AICommander.c') 'GetMaximumVehiclePresetCost').Replace('FactionKey stableKey','string stableKey').Replace('for (int index;','for (int index=0;').Replace('int maximum;','int maximum=0;').Replace('AICF_VehiclePresetCatalog catalog;','AICF_VehiclePresetCatalog catalog=null;')
$covered=(Body $planner 'Covered').Replace('foreach (IEntity entity : m_aInventory)','foreach (IEntity entity in m_aInventory)')
$covered=[regex]::Replace($covered,'FindComponent\((SCR_\w+)\)','FindComponent(typeof($1))')
$covered=$covered.Replace('SCR_EditableEntityUIInfo info;','SCR_EditableEntityUIInfo info=null;')
$resolver=(Body $profile 'ResolveSupplyDepotPrefab').Replace('ResourceName existing','string existing').Replace('ResourceName selected','string selected').Replace('array<ResourceName> candidates','Arr<string> candidates').Replace('foreach (ResourceName candidate : candidates)','foreach (string candidate in candidates)').Replace('m_aSupplyPrefabFactions.Remove(cached)','m_aSupplyPrefabFactions.RemoveAt(cached)').Replace('m_aSupplyPrefabs.Remove(cached)','m_aSupplyPrefabs.RemoveAt(cached)').Replace('m_aSupplyPrefabFactions.Insert(faction)','m_aSupplyPrefabFactions.Add(faction)').Replace('m_aSupplyPrefabs.Insert(selected)','m_aSupplyPrefabs.Add(selected)').Replace('int examined;','int examined=0;').Replace('System.GetTickCount()','Clock.Now').Replace('string.Format','SF.Format').Replace('for (int pass;', 'for (int pass=0;').Replace('name.ToLower();','name = name.ToLowerInvariant();')
$ctor=(Body $order 'AICF_ConstructionBaseState').Replace('Resize(AICF_EConstructionType.COUNT)','Resize((int)AICF_EConstructionType.COUNT)')
$reset=[regex]::Match((Body $planner 'Decide'),'for \(int resetType; resetType < AICF_EConstructionType.COUNT; resetType\+\+\)\s*\{[^{}]+\}').Value.Replace('int resetType;','int resetType=0;').Replace('resetType < AICF_EConstructionType.COUNT','resetType < (int)AICF_EConstructionType.COUNT')
if(!$reset){throw 'Missing actual per-type reset loop'}
$cancel=(Body $planner 'Cancel').Replace('System.GetTickCount()','Clock.Now').Replace('string.Format','SF.Format').Replace('for (int pass;', 'for (int pass=0;').Replace('name.ToLower();','name = name.ToLowerInvariant();').Replace('[order.m_eType]','[(int)order.m_eType]').Replace('(order.m_eType + 1) % AICF_EConstructionType.COUNT','((int)order.m_eType + 1) % (int)AICF_EConstructionType.COUNT').Replace('state.m_iNextType = AICF_EConstructionType.SMALL_BARRACKS;','state.m_iNextType = (int)AICF_EConstructionType.SMALL_BARRACKS;')
$rhsMeta=(Body $rhs 'IsSupplyDepotMetadata').Replace('super.','base.').Replace('FactionKey stableKey','string stableKey')
$rhsAlias=(Body $rhs 'AllowsConstructionMetadataAlias').Replace('FactionKey stableKey','string stableKey')
$enum=[regex]::Match($order,'enum AICF_EConstructionType\s*\{[^}]+\}').Value
if(!$enum){throw 'Missing actual stable construction enum'}
