}
'@
$shim=$shim.Replace('__ENUM__',('public '+$enum)).Replace('__QUOTE__',$quote).Replace('__COVERED__',$covered).Replace('__LABEL__',(Body $metadata 'ServiceLabel')).Replace('__SERVICE__',(Body $metadata 'ServiceType')).Replace('__META__',(Body $profile 'IsSupplyDepotMetadata')).Replace('__RESOLVER__',$resolver).Replace('__CTOR__',$ctor).Replace('__RESET__',$reset).Replace('__CANCEL__',$cancel).Replace('__CORE_ALIAS__',(Body $profile 'AllowsConstructionMetadataAlias')).Replace('__RUNTIME__',(Body $rhs 'GetRuntimeFactionKey')).Replace('__STABLE__',(Body $rhs 'GetStableFactionKey')).Replace('__RHS_META__',$rhsMeta).Replace('__RHS_ALIAS__',$rhsAlias).Replace('public SCR_EServicePointType GetType()','public new SCR_EServicePointType GetType()')
$ns='SupplyDepot'+[guid]::NewGuid().ToString('N')
Add-Type -TypeDefinition $shim.Replace('__NS__',$ns) -WarningAction SilentlyContinue
$count=([type]($ns+'.Suite'))::Run()
$unsafe=@(
 @{source=$shim.Replace('if ((pass == 0 && !hint) || (pass == 1 && hint)) continue;','');failure='hint success does not load unrelated helipad'},
 @{source=$shim.Replace('pass < 2','pass < 1');failure='unknown registered storage name retains generic fallback'},
 @{source=$shim.Replace('maximum = Math.Max(maximum, catalog.Cost(preset.m_sPrefab));','maximum += catalog.Cost(preset.m_sPrefab);');failure='maximum single purchase instead of sum'},
 @{source=$shim.Replace('commander.GetMaximumVehiclePresetCost() <= order.m_Base.GetSuppliesMax()','commander.GetMaximumVehiclePresetCost() >= order.m_Base.GetSuppliesMax()');failure='MOB1000 cannot cover3750'},
 @{source=$shim.Replace('!composition || composition.IsCompositionSpawned()','!composition || !composition.IsCompositionSpawned()');failure='online storage with insufficient aggregate capacity does not cap demand'},
 @{source=$shim.Replace('Resize((int)AICF_EConstructionType.COUNT)','Resize(5)');failure='actual constructor sizes all type arrays by COUNT'},
 @{source=$shim.Replace('prefab != GetConstructionPrefab(stableKey, type) || ','');failure='unselected or unregistered legacy resource rejected'},
 @{source=$shim.Replace('type != AICF_EConstructionType.SUPPLY_DEPOT || ','');failure='legacy alias limited to storage construction type'}
)
foreach($variant in $unsafe){
 $bad='SupplyDepotUnsafe'+[guid]::NewGuid().ToString('N')
 Add-Type -TypeDefinition $variant.source.Replace('__NS__',$bad) -WarningAction SilentlyContinue
 $caught=$false
 try{[void]([type]($bad+'.Suite'))::Run()}catch{if($_.Exception.ToString().Contains($variant.failure)){$caught=$true}else{throw}}
 if(!$caught){throw "Unsafe variant accepted: $($variant.failure)"}
}
if($quote -match 'AddSupplies|SetSuppliesMax|SpawnEntity|\.Inspect\(|SetVehiclePreset|GetGroup\('){throw 'Commander demand must stay read-only without live roster dependency'}
$commander=Body $planner 'Commander'
if(!$commander.Contains('AllowsAutomaticConstruction(faction.GetFactionKey())')){throw 'Co-op human automatic construction veto removed'}
if(!(Body $profile 'GetConstructionPrefab').Contains('ResolveSupplyDepotPrefab(faction, manager, GetGame().GetWorld())') -or !(Body $profile 'ResolveSupplyDepotPrefab').Contains('faction.GetBuildingPrefab(EEditableEntityLabel.SERVICE_SUPPLY_STORAGE)')){throw 'Storage must come from native faction and registered manager, no prefab hardcoding'}
if(!(Body $rhs 'GetConstructionPrefab').Contains('if (type == AICF_EConstructionType.SUPPLY_DEPOT) return super.GetConstructionPrefab(stableKey, type);')){throw 'RHS supply storage must use native faction resource'}
if(@([regex]::Matches((Body $metadata 'Load'),'AllowsConstructionMetadataAlias\(prefab, type, faction, info\)')).Count -ne 2){throw 'Metadata faction key and label must use the same narrowly scoped profile alias policy'}
Write-Output "PASS native supply depot demand actual predicates=$count unsafe_variants=$($unsafe.Count); stable enum/faction/native metadata/authority boundaries retained"
